mapper.select:
SELECT m.id AS music_id, m.title, m.artist,

FROM music m




				point((m.location::real[])[${box.axisX}], (m.location::real[])[${box.axisY}])
				<@ box(point(#{box.xMin}, #{box.yMin}), point(#{box.xMax}, #{box.yMax}))


				(m.location::real[])[${box.axisX}] BETWEEN #{box.xMin} AND #{box.xMax}
				AND (m.location::real[])[${box.axisY}] BETWEEN #{box.yMin} AND #{box.yMax}



	AND NOT m.is_unplayable

LIMIT #{limit}
